sql:
SELECT SUM(profit) AS total_profit_tenant_7
FROM ledger
WHERE tenant_name = 'Tenant 7';

SELECT SUM(profit) AS total_profit_tenant_11
FROM ledger
WHERE tenant_name = 'Tenant 11';

SELECT SUM(profit) AS total_profit_tenant_1
FROM ledger
WHERE tenant_name = 'Tenant 1';

SELECT COUNT(DISTINCT tenant_name) AS num_tenants
FROM ledger
WHERE tenant_name IS NOT NULL;

SELECT COUNT(DISTINCT ledger_category) AS distinct_expense_categories
FROM ledger
WHERE ledger_type = 'expenses';

SELECT
  ROUND(SUM(profit) / COUNT(DISTINCT month), 2) AS avg_monthly_profit
FROM ledger;
